record.field:
if record.ticket_id:
  company_id = env.context.get('allowed_company_ids', [env.user.company_id.id])[0]
  company = env['res.company'].browse(company_id)
  
  if (record.x_studio_repair_rug == True or record.x_studio_repair_normal_with_serial_no == True):
    if company.id == 1:
      ticket = env['helpdesk.ticket'].search([('id', '=', record.ticket_id.id),('company_id', '=', company.id)],limit=1)
      if ticket:
        if record.location_id.id != record.x_studio_suggested_location_id.id:
          raise UserError("Return Location should be equal to Suggested Return Location.")
    else:
      ticket = env['helpdesk.ticket'].search([('id', '=', record.ticket_id.id),('company_id', '=', company.id)],limit=1)
      if ticket:
        if record.location_id.id != record.x_studio_suggested_location_id_1.id:
          raise UserError('Return Location should be equal to Suggested Return Location.')

select = 0
formula = ''
formula2 = ''
for indicator_line in record.x_studio_temp_structure_details:
  if (indicator_line.x_studio_select == True):
    select += 1
    formula += "[" + indicator_line.x_studio_charge_name + "]"

if select == 0:
 raise UserError("Atleast One Line Should be Selected.")
 
update_formula = env['x_structure_details'].search([('id', '=', record.x_studio_temp_structure_details_id.id)],limit=1)
if update_formula:
  if update_formula.x_studio_formula:
    formula2 = update_formula.x_studio_formula + formula
  else:
    formula2 = formula
    
  update_formula.write({'x_studio_formula':formula2})

if record.id:
  temp_rec = env['x_temp_structure_maste'].search([('id', '=', record.id)],limit=1)
  temp_rec.unlink()
